using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ── CalculateTotal: DataRow-driven tests ────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.10, 0.00, DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00, DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0, 199.98, DisplayName = "Max tax rate (100%)")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    // ── CalculateTotal: DynamicData-driven tests ────────────────────────

    public static IEnumerable<object[]> InvalidCalculateTotalInputs
    {
        get
        {
            yield return new object[] { -1m, 1, 0.1m, "unitPrice", "Negative unit price" };
            yield return new object[] { 10m, -1, 0.1m, "quantity", "Negative quantity" };
            yield return new object[] { 10m, 1, -0.1m, "taxRate", "Negative tax rate" };
            yield return new object[] { 10m, 1, 1.1m, "taxRate", "Tax rate above 1" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidCalculateTotalInputs), DynamicDataDisplayName = nameof(GetCalculateTotalDisplayName))]
    public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
        decimal unitPrice, int quantity, decimal taxRate, string expectedParamName, string _)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(unitPrice, quantity, taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    public static string GetCalculateTotalDisplayName(MethodInfo _, object[] data) => (string)data[4];

    // ── ApplyDiscount: DataRow-driven tests ─────────────────────────────

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "0% discount")]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% discount")]
    [DataRow(100.00, 50.0, 50.00, DisplayName = "50% discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount")]
    [DataRow(49.99, 25.0, 37.4925, DisplayName = "Fractional result")]
    [DataRow(0.00, 50.0, 0.00, DisplayName = "Zero price with discount")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        double price, double discountPercent, double expectedPrice)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expectedPrice, result);
    }

    // ── ApplyDiscount: DynamicData-driven boundary tests ────────────────

    public static IEnumerable<object[]> InvalidDiscountInputs
    {
        get
        {
            yield return new object[] { 100m, -1m, "Negative discount" };
            yield return new object[] { 100m, 101m, "Discount over 100%" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountInputs), DynamicDataDisplayName = nameof(GetDiscountDisplayName))]
    public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent, string _)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    public static string GetDiscountDisplayName(MethodInfo _, object[] data) => (string)data[2];

    // ── FormatPrice: DataRow-driven tests ───────────────────────────────

    [TestMethod]
    [DataRow(19.99, "$", "$19.99", DisplayName = "Dollar format")]
    [DataRow(19.99, "€", "€19.99", DisplayName = "Euro format")]
    [DataRow(5.1, "$", "$5.10", DisplayName = "Pads to two decimals")]
    [DataRow(0.0, "$", "$0.00", DisplayName = "Zero price")]
    public void FormatPrice_WithCurrencySymbol_ReturnsFormattedString(
        double price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice((decimal)price, symbol);

        Assert.AreEqual(expected, result);
    }
}

